using UnifiedMediaHub.Core;using Xunit;
namespace UnifiedMediaHub.Tests;
// A Telegram message whose media is a file, voice note or sticker never resolves to an
// image/video (the kind comes from MIME), so it must be skipped instead of stopping the batch.
public sealed class TelegramUnsupportedMediaTests
{
 [Theory][InlineData(1)][InlineData(200)]public async Task UnsupportedMessagesAreSkippedAndTheRestDownload(int batchSize){var root=Path.Combine(Path.GetTempPath(),"umh-tg-skip-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{using var repo=new HubRepository(Path.Combine(root,"hub.db"));repo.Initialize();var job=repo.CreateJob(new(){Platform="telegram",Kind="chat",Url="https://t.me/c/7",ChatId="channel_7",AccountId="123"},root);repo.UpsertItems(job.Id,Enumerable.Range(1,3).Select(i=>new ContentItem{Key="telegram:channel_7:"+i,Platform="telegram",ContentId=i.ToString(),ChatId="channel_7",MessageId=i.ToString(),SourceUrl="https://t.me/c/7/"+i,Selected=true,MediaResolved=i!=2,Media=i==2?[]:[new(){Index=1,Kind="image",Extension="jpg"}]}));var received=new List<string>();var runner=new FixtureRunner(async(request,emit,_ct)=>{if(request.Operation!="download")return;await emit(new(){Type="account",Platform="telegram",Authenticated=true,AccountId="123"});foreach(var item in request.Items!){Assert.True(item.MediaResolved);received.Add(item.ContentId);var file=Path.Combine(root,item.ContentId+".jpg");byte[] bytes=[1,2,3];File.WriteAllBytes(file,bytes);await emit(new(){Type="receipt",Receipt=new(){ContentKey=item.Key,MediaIndex=1,FilePath=file,Bytes=bytes.Length,Sha256=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(bytes)),Status="completed"}});}await emit(new(){Type="complete",Status="completed",Completeness="unknown"});});await using var hub=new HubCoordinator(repo,runner,new(){DataRoot=root,DownloadRoot=root},batchSize);hub.Enable();await hub.Submit(job.Id,"download");var state=repo.GetJob(job.Id)!;Assert.True(received.SequenceEqual(new[]{"1","3"}),$"received {string.Join(",",received)}; {state.Status} {state.ReasonCode} {state.Message}");Assert.Equal(2,repo.ListReceipts(job.Id).Count);var done=repo.GetJob(job.Id)!;Assert.Equal("completed",done.Status);Assert.Equal("media_unsupported",done.ReasonCode);Assert.Contains("跳过 1",done.Message);}finally{Directory.Delete(root,true);}}
}
